public class Solution {
    public bool SearchKey(ListNode head, int key) {
        if (head == null) {
            return false;
        }

        ListNode current = head;

        do {
            if (current.val == key) {
                return true;
            }

            current = current.next;
        } while (current != null);

        return false;
    }
}
```

Time complexity: `O(n)` in the worst case, with an earlier return when a value matches.

Space complexity: `O(1)`.

